create or replace function public.support_ticket_access(p_ticket uuid,p_admin boolean default false)returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.support_tickets t where t.id=p_ticket and(t.opened_by=auth.uid()or(p_admin and public.admin_has_permission('support.manage'))))$$;
create or replace function public.create_support_ticket(p_data jsonb,p_idempotency_key text)returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare v_id uuid;v_role text;begin if auth.uid()is null or length(p_idempotency_key)not between 8 and 120 then raise exception 'Invalid request';end if;v_role:=p_data->>'requester_role';if v_role not in('customer','provider','contractor','driver','admin')or length(btrim(p_data->>'subject'))<3 or length(btrim(p_data->>'description'))<10 then raise exception 'Invalid ticket';end if;perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_idempotency_key,0));select id into v_id from public.support_tickets where opened_by=auth.uid()and message=p_idempotency_key;if found then return v_id;end if;insert into public.support_tickets(ticket_code,opened_by,subject,category,priority,message,description,requester_role,related_entity_type,related_entity_id,status)values('SUP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),auth.uid(),btrim(p_data->>'subject'),btrim(p_data->>'category'),coalesce(nullif(p_data->>'priority',''),'normal')::public.support_ticket_priority,p_idempotency_key,btrim(p_data->>'description'),v_role,nullif(btrim(p_data->>'related_entity_type'),''),nullif(p_data->>'related_entity_id','')::uuid,'open')returning id into v_id;insert into public.support_messages(ticket_id,author_profile_id,body,event_key)values(v_id,auth.uid(),btrim(p_data->>'description'),'ticket-created:'||v_id);insert into public.outbox_events(aggregate_type,aggregate_id,event_type,payload,idempotency_key)values('support_ticket',v_id,'ticket.created',jsonb_build_object('actor_id',auth.uid()),'ticket-created:'||v_id);return v_id;end$$;
create or replace function public.reply_support_ticket(p_ticket uuid,p_body text,p_internal boolean,p_idempotency_key text)returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare v_id uuid;v_ticket public.support_tickets%rowtype;v_admin boolean:=public.admin_has_permission('support.manage');begin select*into v_ticket from public.support_tickets where id=p_ticket for update;if not found or(v_ticket.opened_by<>auth.uid()and not v_admin)or(p_internal and not v_admin)or v_ticket.status='closed'or length(btrim(p_body))<2 then raise exception 'Reply not allowed';end if;insert into public.support_messages(ticket_id,author_profile_id,body,is_internal,event_key)values(p_ticket,auth.uid(),btrim(p_body),p_internal,p_idempotency_key)on conflict(event_key)where event_key is not null do update set event_key=excluded.event_key returning id into v_id;if not p_internal then insert into public.outbox_events(aggregate_type,aggregate_id,event_type,payload,idempotency_key)values('support_ticket',p_ticket,'ticket.replied',jsonb_build_object('actor_id',auth.uid()),'ticket-replied:'||v_id)on conflict(idempotency_key)where idempotency_key is not null do nothing;end if;return v_id;end$$;
create or replace function public.transition_support_ticket(p_ticket uuid,p_action text,p_reason text default null,p_assignee uuid default null)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare v public.support_tickets%rowtype;v_admin boolean:=public.admin_has_permission('support.manage');v_event text;begin select*into v from public.support_tickets where id=p_ticket for update;if not found then raise exception 'Ticket not found';end if;if p_action='reopen'and(v.opened_by=auth.uid()or v_admin)and v.status in('resolved','closed')then update public.support_tickets set status='open',resolved_at=null,closed_at=null,updated_at=now()where id=p_ticket;v_event:='ticket.reopened';elsif not v_admin then raise exception 'Support permission required';elsif p_action='assign'then update public.support_tickets set assigned_to=p_assignee,status='in_progress',updated_at=now()where id=p_ticket;v_event:='ticket.assigned';elsif p_action='resolve'then update public.support_tickets set status='resolved',resolved_at=now(),updated_at=now()where id=p_ticket;v_event:='ticket.resolved';elsif p_action='close'then update public.support_tickets set status='closed',closed_at=now(),updated_at=now()where id=p_ticket;v_event:='ticket.resolved';elsif p_action='escalate'then update public.support_tickets set escalation_level=least(5,escalation_level+1),escalated_at=now(),priority='high',updated_at=now()where id=p_ticket;v_event:='ticket.escalated';else raise exception 'Invalid transition';end if;insert into public.audit_logs(actor_profile_id,entity_table,entity_id,action,new_data)values(auth.uid(),'support_tickets',p_ticket::text,p_action,jsonb_build_object('reason',p_reason,'assignee',p_assignee));insert into public.outbox_events(aggregate_type,aggregate_id,event_type,payload,idempotency_key)values('support_ticket',p_ticket,v_event,jsonb_build_object('actor_id',auth.uid()),v_event||':'||p_ticket||':'||extract(epoch from now())::bigint);end$$;

