create or replace function public.save_contractor_bank_account(p_id uuid,p_bank text,p_name text,p_iban text,p_default boolean)returns uuid language plpgsql security definer set search_path=public,extensions,pg_temp as $$declare v_c uuid;v_id uuid;v_clean text;begin select id into v_c from public.contractor_profiles where profile_id=auth.uid();v_clean:=upper(regexp_replace(p_iban,'\s','','g'));if v_c is null or v_clean!~'^SA[0-9]{22}$'then raise exception 'Invalid bank account';end if;if p_default then update public.contractor_bank_accounts set is_default=false where contractor_profile_id=v_c;end if;if p_id is null then insert into public.contractor_bank_accounts(contractor_profile_id,bank_name,account_name,iban_encrypted,iban_last4,iban_fingerprint,is_default,is_active)values(v_c,btrim(p_bank),btrim(p_name),encode(digest(v_clean,'sha256'),'hex'),right(v_clean,4),encode(digest(v_clean,'sha256'),'hex'),p_default,true)returning id into v_id;else update public.contractor_bank_accounts set bank_name=btrim(p_bank),account_name=btrim(p_name),iban_encrypted=encode(digest(v_clean,'sha256'),'hex'),iban_last4=right(v_clean,4),iban_fingerprint=encode(digest(v_clean,'sha256'),'hex'),is_default=p_default,updated_at=now()where id=p_id and contractor_profile_id=v_c returning id into v_id;if v_id is null then raise exception 'Account not found';end if;end if;return v_id;end$$;
create or replace function public.set_contractor_bank_account_state(p_id uuid,p_active boolean,p_default boolean)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare v_c uuid;begin select id into v_c from public.contractor_profiles where profile_id=auth.uid();if p_default and p_active then update public.contractor_bank_accounts set is_default=false where contractor_profile_id=v_c;end if;update public.contractor_bank_accounts set is_active=p_active,is_default=p_default and p_active,updated_at=now()where id=p_id and contractor_profile_id=v_c;if not found then raise exception 'Account not found';end if;end$$;
create or replace function public.request_contractor_settlement(p_amount numeric,p_bank uuid,p_notes text,p_idempotency_key text)returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare v_c uuid;v_available numeric;v_reserved numeric;v_id uuid;begin select id into v_c from public.contractor_profiles where profile_id=auth.uid();if v_c is null or p_amount<=0 or length(p_idempotency_key)not between 8 and 120 or not exists(select 1 from public.contractor_bank_accounts where id=p_bank and contractor_profile_id=v_c and is_active)then raise exception 'Invalid settlement request';end if;perform pg_advisory_xact_lock(hashtextextended(v_c::text||':settlement',0));select id into v_id from public.contractor_settlement_requests where contractor_profile_id=v_c and idempotency_key=p_idempotency_key;if found then return v_id;end if;select coalesce(sum(case when financial_kind in('advance','milestone_payment','final_payment','refund','adjustment')then amount else-abs(amount)end)filter(where status in('available','completed')),0)into v_available from public.contractor_financial_transactions where contractor_profile_id=v_c;select coalesce(sum(amount),0)into v_reserved from public.contractor_settlement_requests where contractor_profile_id=v_c and workflow_status in('requested','under_review','approved','processing');if p_amount>v_available-v_reserved then raise exception 'Insufficient available balance';end if;insert into public.contractor_settlement_requests(settlement_code,contractor_profile_id,bank_account_id,amount,notes,status,workflow_status,idempotency_key)values('SET-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),v_c,p_bank,p_amount,nullif(btrim(p_notes),''),'pending_review','requested',p_idempotency_key)returning id into v_id;insert into public.outbox_events(aggregate_type,aggregate_id,event_type,payload,idempotency_key)values('contractor_settlement',v_id,'settlement.requested',jsonb_build_object('contractor_id',v_c),'settlement-requested:'||v_id);return v_id;end$$;
create or replace function public.transition_contractor_settlement(p_id uuid,p_action text,p_reason text,p_reference text,p_idempotency_key text)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare v public.contractor_settlement_requests%rowtype;v_next text;begin if not public.admin_has_permission('finance.manage')or length(p_idempotency_key)<8 then raise exception 'Finance permission required';end if;select*into v from public.contractor_settlement_requests where id=p_id for update;if not found then raise exception 'Settlement not found';end if;v_next:=case when p_action='review'and v.workflow_status='requested'then'under_review' when p_action='approve'and v.workflow_status='under_review'then'approved' when p_action='reject'and v.workflow_status in('requested','under_review')and length(btrim(p_reason))>=5 then'rejected' when p_action='process'and v.workflow_status='approved'then'processing' when p_action='paid'and v.workflow_status='processing'and length(btrim(p_reference))>=4 then'paid' when p_action='fail'and v.workflow_status='processing'and length(btrim(p_reason))>=5 then'failed' when p_action='cancel'and v.workflow_status in('requested','under_review')then'cancelled' else null end;if v_next is null then raise exception 'Invalid settlement transition';end if;update public.contractor_settlement_requests set workflow_status=v_next,status=case v_next when'approved'then'approved'::public.contractor_settlement_status when'processing'then'transferring'::public.contractor_settlement_status when'paid'then'transferred'::public.contractor_settlement_status when'rejected'then'rejected'::public.contractor_settlement_status else status end,reviewed_by=auth.uid(),reviewed_at=case when v_next in('approved','rejected')then now()else reviewed_at end,review_notes=nullif(btrim(p_reason),''),payment_reference=case when v_next='paid'then btrim(p_reference)else payment_reference end,failure_reason=case when v_next='failed'then btrim(p_reason)else null end,updated_at=now()where id=p_id;if v_next='paid'then insert into public.contractor_financial_transactions(transaction_code,contractor_profile_id,project_id,transaction_type,financial_kind,amount,status,balance_after,reference)select'CTX-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),v.contractor_profile_id,t.project_id,'settlement','adjustment',-v.amount,'completed',greatest(0,t.balance_after-v.amount),btrim(p_reference)from public.contractor_financial_transactions t where t.contractor_profile_id=v.contractor_profile_id order by t.occurred_at desc limit 1;end if;insert into public.audit_logs(actor_profile_id,contractor_profile_id,entity_table,entity_id,action,new_data)values(auth.uid(),v.contractor_profile_id,'contractor_settlement_requests',p_id::text,'settlement_'||v_next,jsonb_build_object('reason',p_reason,'reference',p_reference));insert into public.outbox_events(aggregate_type,aggregate_id,event_type,payload,idempotency_key)values('contractor_settlement',p_id,'settlement.'||v_next,jsonb_build_object('contractor_id',v.contractor_profile_id,'reason',p_reason),'settlement-transition:'||p_id||':'||p_idempotency_key)on conflict(idempotency_key)where idempotency_key is not null do nothing;end$$;

