create or replace function public.schedule_operational_notifications()returns integer language plpgsql security definer set search_path=public,pg_temp as $$declare v_count integer:=0;v_added integer;begin if coalesce(auth.jwt()->>'role','')<>'service_role'then raise exception 'Service role required';end if;insert into public.outbox_events(aggregate_type,aggregate_id,event_type,payload,idempotency_key)select'contractor_document',d.id,case when d.expires_at<current_date then'contractor.document_expired'else'contractor.document_expiring'end,jsonb_build_object('contractor_id',d.contractor_profile_id,'expires_at',d.expires_at),case when d.expires_at<current_date then'document-expired:'else'document-expiring:'end||d.id from public.contractor_documents d where d.contractor_profile_id is not null and d.expires_at is not null and d.expires_at<=current_date+30 on conflict(idempotency_key)where idempotency_key is not null do nothing;get diagnostics v_added=row_count;v_count:=v_count+v_added;return v_count;end$$;
